//! Per-engine Unicode tables, generated by querying each real engine (see `tools/`).
//!
//! Each engine pins its own Unicode version and has its own definitions (Python's `\w` uses
//! `str.isalnum()`, not UTS #18), so tables are measured from the engine rather than derived
//! from the Unicode Character Database. Regenerate when the pinned engine version changes.

#[allow(clippy::all)]
pub mod go;
#[allow(clippy::all)]
pub mod java;
#[allow(clippy::all)]
pub mod js;
#[allow(clippy::all)]
pub mod python;

use crate::charset::CharSet;
use std::sync::OnceLock;

/// A lazily built `CharSet` from a generated range table.
pub struct Table {
    ranges: &'static [(u32, u32)],
    cell: OnceLock<CharSet>,
}

impl Table {
    pub const fn new(ranges: &'static [(u32, u32)]) -> Self {
        Table {
            ranges,
            cell: OnceLock::new(),
        }
    }

    pub fn get(&self) -> &CharSet {
        self.cell
            .get_or_init(|| CharSet::from_ranges(self.ranges.iter().copied()))
    }
}

/// Closure of `set` under a generated case-insensitivity relation.
pub fn fold_with(set: &CharSet, relation: &[(u32, &[u32])]) -> CharSet {
    let mut extra = Vec::new();
    for &(c, partners) in relation {
        if let Some(ch) = char::from_u32(c)
            && set.contains(ch)
        {
            extra.extend(partners.iter().map(|&d| (d, d)));
        }
    }
    if extra.is_empty() {
        set.clone()
    } else {
        set.union(&CharSet::from_ranges(extra))
    }
}

/// CPython's `\w`, for word boundaries.
pub fn python_word() -> &'static CharSet {
    static T: Table = Table::new(python::WORD);
    T.get()
}

/// JavaScript `\w` under `iu`, for word boundaries.
pub fn js_word_iu() -> &'static CharSet {
    static T: Table = Table::new(js::WORD_IU);
    T.get()
}

/// Java non-spacing marks and letter-or-digit, for Java's `\b`.
pub fn java_marks() -> (&'static CharSet, &'static CharSet) {
    static MN: Table = Table::new(java::NON_SPACING_MARK);
    static LD: Table = Table::new(java::LETTER_OR_DIGIT);
    (MN.get(), LD.get())
}
